CREATE TYPE public.app_role AS ENUM ('super_admin','admin','agent','viewer');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND p.active) $$;
CREATE FUNCTION public.is_team() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=(SELECT auth.uid()) AND p.active) $$;
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role((SELECT auth.uid()),'admin') OR public.has_role((SELECT auth.uid()),'super_admin') $$;
CREATE FUNCTION public.can_source() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin() OR public.has_role((SELECT auth.uid()),'agent') $$;
REVOKE EXECUTE ON FUNCTION public.has_role(uuid,public.app_role),public.is_team(),public.is_admin(),public.can_source() FROM public,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role),public.is_team(),public.is_admin(),public.can_source() TO authenticated,service_role;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=(SELECT auth.uid()) OR (SELECT public.is_admin()));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=(SELECT auth.uid()) OR (SELECT public.is_admin()));
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER create_team_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, role public.app_role NOT NULL, invited_user_id uuid, invited_by uuid, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','revoked')), expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.user_invitations TO authenticated; GRANT ALL ON public.user_invitations TO service_role; ALTER TABLE public.user_invitations ENABLE ROW LEVEL SECURITY; CREATE POLICY invitations_admin ON public.user_invitations FOR SELECT TO authenticated USING ((SELECT public.is_admin()));
CREATE TABLE public.product_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_categories TO authenticated; GRANT ALL ON public.product_categories TO service_role; ALTER TABLE public.product_categories ENABLE ROW LEVEL SECURITY;
INSERT INTO public.product_categories(name) VALUES ('Fashion Accessories'),('Home & Living'),('Home Organization'),('Desk Accessories'),('Gifts'),('Lifestyle'),('Educational Toys'),('Personal Accessories'),('Other');
CREATE TABLE public.sourcing_visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL DEFAULT auth.uid(), market text NOT NULL, notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','submitted')), started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.sourcing_visits TO authenticated; GRANT ALL ON public.sourcing_visits TO service_role; ALTER TABLE public.sourcing_visits ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_by uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL,contact_person text NOT NULL,mobile text NOT NULL,shop_number text NOT NULL,market text NOT NULL,address text NOT NULL,visit_date date NOT NULL, type text NOT NULL DEFAULT 'Wholesaler',relationship text NOT NULL DEFAULT 'New', notes text NOT NULL DEFAULT '',details jsonb NOT NULL DEFAULT '{}', latitude double precision NOT NULL,longitude double precision NOT NULL,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.suppliers TO authenticated; GRANT ALL ON public.suppliers TO service_role; ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.supplier_photos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),supplier_id uuid NOT NULL REFERENCES public.suppliers(id) ON DELETE CASCADE,path text NOT NULL,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.supplier_photos TO authenticated; GRANT ALL ON public.supplier_photos TO service_role; ALTER TABLE public.supplier_photos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visit_suppliers(visit_id uuid REFERENCES public.sourcing_visits(id) ON DELETE CASCADE,supplier_id uuid REFERENCES public.suppliers(id) ON DELETE CASCADE,PRIMARY KEY(visit_id,supplier_id));
GRANT SELECT,INSERT ON public.visit_suppliers TO authenticated; GRANT ALL ON public.visit_suppliers TO service_role; ALTER TABLE public.visit_suppliers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),supplier_id uuid NOT NULL REFERENCES public.suppliers(id),category_id uuid NOT NULL REFERENCES public.product_categories(id),visit_id uuid REFERENCES public.sourcing_visits(id),created_by uuid NOT NULL DEFAULT auth.uid(),name text NOT NULL,description text NOT NULL,quality text NOT NULL CHECK(quality IN ('Premium','Standard','Budget','Needs Verification')),material text NOT NULL DEFAULT '',moq integer NOT NULL DEFAULT 1 CHECK(moq>0),stock integer CHECK(stock>=0),color_mode text NOT NULL DEFAULT 'No' CHECK(color_mode IN ('Yes','No','Not Applicable')),size_mode text NOT NULL DEFAULT 'No' CHECK(size_mode IN ('Yes','No','Not Applicable')),details jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted')),latitude double precision NOT NULL,longitude double precision NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.product_photos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,path text NOT NULL,view text NOT NULL DEFAULT 'Front',created_by uuid NOT NULL DEFAULT auth.uid());
GRANT SELECT,INSERT,DELETE ON public.product_photos TO authenticated; GRANT ALL ON public.product_photos TO service_role; ALTER TABLE public.product_photos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.product_colors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,name text NOT NULL,code text,photos text[] NOT NULL CHECK(cardinality(photos)>0),availability text NOT NULL DEFAULT 'Available',remarks text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_colors TO authenticated; GRANT ALL ON public.product_colors TO service_role; ALTER TABLE public.product_colors ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.product_sizes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,name text NOT NULL,availability text NOT NULL DEFAULT 'Available',remarks text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_sizes TO authenticated; GRANT ALL ON public.product_sizes TO service_role; ALTER TABLE public.product_sizes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.product_variations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,kind text NOT NULL,name text NOT NULL,photos text[] NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_variations TO authenticated; GRANT ALL ON public.product_variations TO service_role; ALTER TABLE public.product_variations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.product_price_tiers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,quantity integer NOT NULL CHECK(quantity>0),unit_price numeric(12,2) CHECK(unit_price>0),unavailable boolean NOT NULL DEFAULT false,CHECK((unavailable AND unit_price IS NULL) OR (NOT unavailable AND unit_price IS NOT NULL)),UNIQUE(product_id,quantity));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_price_tiers TO authenticated; GRANT ALL ON public.product_price_tiers TO service_role; ALTER TABLE public.product_price_tiers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.product_evaluations(product_id uuid PRIMARY KEY REFERENCES public.products(id) ON DELETE CASCADE,favorite boolean NOT NULL DEFAULT false,score integer CHECK(score BETWEEN 1 AND 10),status text NOT NULL DEFAULT 'Unreviewed',notes text NOT NULL DEFAULT '',updated_by uuid NOT NULL DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE ON public.product_evaluations TO authenticated; GRANT ALL ON public.product_evaluations TO service_role; ALTER TABLE public.product_evaluations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.supplier_ratings(supplier_id uuid PRIMARY KEY REFERENCES public.suppliers(id) ON DELETE CASCADE,rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),notes text NOT NULL DEFAULT '',updated_by uuid NOT NULL DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE ON public.supplier_ratings TO authenticated; GRANT ALL ON public.supplier_ratings TO service_role; ALTER TABLE public.supplier_ratings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.gps_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_by uuid NOT NULL DEFAULT auth.uid(),visit_id uuid REFERENCES public.sourcing_visits(id),supplier_id uuid REFERENCES public.suppliers(id),product_id uuid REFERENCES public.products(id),kind text NOT NULL,latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180),accuracy double precision,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.gps_records TO authenticated; GRANT ALL ON public.gps_records TO service_role; ALTER TABLE public.gps_records ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.activity_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid DEFAULT auth.uid(),action text NOT NULL,entity_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_logs TO authenticated; GRANT ALL ON public.activity_logs TO service_role; ALTER TABLE public.activity_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY logs_read ON public.activity_logs FOR SELECT TO authenticated USING ((SELECT public.is_admin()) OR user_id=(SELECT auth.uid()));
CREATE TABLE public.company_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),company_name text NOT NULL DEFAULT 'TASMEEM',notifications boolean NOT NULL DEFAULT true);
GRANT SELECT,UPDATE ON public.company_settings TO authenticated; GRANT ALL ON public.company_settings TO service_role; ALTER TABLE public.company_settings ENABLE ROW LEVEL SECURITY; INSERT INTO public.company_settings(id) VALUES(true);
CREATE POLICY settings_read ON public.company_settings FOR SELECT TO authenticated USING ((SELECT public.is_team())); CREATE POLICY settings_write ON public.company_settings FOR UPDATE TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()),'super_admin'))) WITH CHECK ((SELECT public.has_role((SELECT auth.uid()),'super_admin')));
CREATE POLICY categories_read ON public.product_categories FOR SELECT TO authenticated USING ((SELECT public.is_team())); CREATE POLICY categories_insert ON public.product_categories FOR INSERT TO authenticated WITH CHECK ((SELECT public.is_admin())); CREATE POLICY categories_update ON public.product_categories FOR UPDATE TO authenticated USING ((SELECT public.is_admin())) WITH CHECK ((SELECT public.is_admin())); CREATE POLICY categories_delete ON public.product_categories FOR DELETE TO authenticated USING ((SELECT public.is_admin()));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['suppliers','products','sourcing_visits'] LOOP EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING ((SELECT public.is_team()))',t||'_read',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK ((SELECT public.can_source()) AND created_by=(SELECT auth.uid()))',t||'_insert',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING ((SELECT public.is_admin()) OR ((SELECT public.can_source()) AND created_by=(SELECT auth.uid()) AND status IN (''draft'',''active''))) WITH CHECK ((SELECT public.is_admin()) OR ((SELECT public.can_source()) AND created_by=(SELECT auth.uid())))',t||'_update',t); EXECUTE format('CREATE INDEX %I ON public.%I(created_by,created_at DESC)',t||'_owner_idx',t); END LOOP; END $$;
CREATE POLICY suppliers_delete ON public.suppliers FOR DELETE TO authenticated USING ((SELECT public.is_admin())); CREATE POLICY products_delete ON public.products FOR DELETE TO authenticated USING ((SELECT public.is_admin()));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['supplier_photos','product_photos','product_colors','product_sizes','product_variations','product_price_tiers','visit_suppliers','gps_records'] LOOP EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING ((SELECT public.is_team()))',t||'_read',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK ((SELECT public.can_source()))',t||'_insert',t); END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['product_evaluations','supplier_ratings'] LOOP EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING ((SELECT public.is_team()))',t||'_read',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK ((SELECT public.is_admin()))',t||'_insert',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING ((SELECT public.is_admin())) WITH CHECK ((SELECT public.is_admin()))',t||'_update',t); END LOOP; END $$;
CREATE INDEX products_supplier_idx ON public.products(supplier_id); CREATE INDEX products_category_idx ON public.products(category_id); CREATE INDEX products_visit_idx ON public.products(visit_id); CREATE INDEX supplier_photos_supplier_idx ON public.supplier_photos(supplier_id); CREATE INDEX product_photos_product_idx ON public.product_photos(product_id); CREATE INDEX product_colors_product_idx ON public.product_colors(product_id); CREATE INDEX product_sizes_product_idx ON public.product_sizes(product_id); CREATE INDEX product_variations_product_idx ON public.product_variations(product_id); CREATE INDEX visit_suppliers_supplier_idx ON public.visit_suppliers(supplier_id); CREATE INDEX gps_records_visit_idx ON public.gps_records(visit_id); CREATE INDEX gps_records_supplier_idx ON public.gps_records(supplier_id); CREATE INDEX gps_records_product_idx ON public.gps_records(product_id); CREATE INDEX gps_records_owner_idx ON public.gps_records(created_by,created_at DESC); CREATE INDEX activity_logs_user_idx ON public.activity_logs(user_id,created_at DESC);
CREATE FUNCTION public.audit_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activity_logs(user_id,action,entity_id) VALUES(auth.uid(),TG_TABLE_NAME||' '||lower(TG_OP),NEW.id); RETURN NEW; END $$;
CREATE TRIGGER suppliers_audit AFTER INSERT OR UPDATE ON public.suppliers FOR EACH ROW EXECUTE FUNCTION public.audit_record(); CREATE TRIGGER products_audit AFTER INSERT OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.audit_record(); CREATE TRIGGER visits_audit AFTER INSERT OR UPDATE ON public.sourcing_visits FOR EACH ROW EXECUTE FUNCTION public.audit_record();
CREATE POLICY sourcing_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='sourcing-photos' AND (SELECT public.is_team())); CREATE POLICY sourcing_photo_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='sourcing-photos' AND (SELECT public.can_source()) AND (storage.foldername(name))[1]=(SELECT auth.uid())::text); CREATE POLICY sourcing_photo_remove ON storage.objects FOR DELETE TO authenticated USING(bucket_id='sourcing-photos' AND ((SELECT public.is_admin()) OR (storage.foldername(name))[1]=(SELECT auth.uid())::text));